        echo "ASK STUDY " . $lbl . " wrote after a Lineup message " . $c['repl'] . " · other business auto-reply " . $c['auto'] . " · opted out " . $c['optout'] . " · decline " . $c['decline'] . " · trivial " . $c['trivial'] . " · REAL " . $c['real'] . " · of them asked price/size/offer " . $c['asked'] . " (ordered within 7 d: " . $c['asked_ord'] . " · were given a price within 3 h: " . $c['asked_priced'] . " · NO price given within 3 h: " . $c['asked_noprice'] . " of which ordered " . $c['asked_noprice_ord'] . ") · did not ask " . $c['not_asked'] . " (ordered " . $c['not_asked_ord'] . ")\n"; } } catch (Throwable $e) { echo "ASK STUDY ERR " . substr($e->getMessage(), 0, 100) . "\n"; }
// 9) the PRICE OFFER (wa_offer.php): a dry run - how many customers would get which offer right now, and 6 sample texts (no phone numbers). Nothing is written or sent.
try { if (!function_exists('setting_get')) { function setting_get($p, $k, $d = '') { $q = $p->prepare("SELECT setting_value FROM hrms_settings WHERE setting_key = ?"); $q->execute([$k]); $v = $q->fetchColumn(); return $v === false ? $d : (string)$v; } }
    if (!function_exists('wa_contact')) { function wa_contact($p, $ph) { $q = $p->prepare("SELECT * FROM wa_contacts WHERE phone = ? LIMIT 1"); $q->execute([$ph]); $r = $q->fetch(PDO::FETCH_ASSOC); return $r ?: null; } }
    require_once $root . 'empmanagment/wa_offer.php'; $GLOBALS['wo_stat'] = []; $smp = []; $t = microtime(true); $r = wof_run($pdo, 3000, $smp, true); ksort($GLOBALS['wo_stat']);
    echo "ASK OFFER (dry run, nothing sent) looked at " . $r[0] . " customers · offers possible " . $r[1] . " · mode " . setting_get($pdo, 'wo_mode', 'dry') . " · " . round(microtime(true) - $t, 1) . " s · " . json_encode($GLOBALS['wo_stat'], JSON_UNESCAPED_UNICODE) . "\n";
    foreach ($smp as $x) echo "ASK OFFER sample " . $x . "\n";
