try { $t00 = date('Y-m-d 00:00:00'); echo "ASK OFFER LOG today by mode/ok/why " . json_encode($one("SELECT mode, ok, SUBSTRING_INDEX(why, ' ', 1) w, COUNT(*) FROM wa_offer WHERE at >= ? GROUP BY mode, ok, w ORDER BY 4 DESC LIMIT 12", [$t00])) . " · by kind (sent) " . json_encode($one("SELECT kind, asked, COUNT(*), ROUND(AVG(pct), 2), ROUND(AVG(price)) FROM wa_offer WHERE ok = 1 AND at >= ? GROUP BY kind, asked", [$t00])) . " · first/last sent " . json_encode($one("SELECT MIN(at), MAX(at) FROM wa_offer WHERE ok = 1 AND at >= ?", [$t00])) . "\n";
    $wm = $pdo->prepare("SELECT SUBSTRING(why, 6) FROM wa_offer WHERE ok = 1 AND at >= ? AND why LIKE 'sent wamid%' LIMIT 400"); $wm->execute([$t00]); $ids = $wm->fetchAll(PDO::FETCH_COLUMN); $stt = [];
    foreach (array_chunk($ids, 200) as $ch) { $y = $pdo->prepare("SELECT status, COALESCE(err_code, 0), COUNT(*) FROM wa_messages WHERE wamid IN (" . implode(',', array_fill(0, count($ch), '?')) . ") GROUP BY status, err_code"); $y->execute($ch); foreach ($y->fetchAll(PDO::FETCH_NUM) as $r) $stt[] = $r; }
    echo "ASK OFFER STATUS (sent ones: status, error code, count) " . json_encode($stt) . " · offers with a customer reply after them " . json_encode($one("SELECT COUNT(DISTINCT o.phone) FROM wa_offer o WHERE o.ok = 1 AND o.at >= ? AND EXISTS (SELECT 1 FROM wa_messages m WHERE m.phone COLLATE utf8mb4_unicode_ci = o.phone COLLATE utf8mb4_unicode_ci AND m.dir = 'in' AND m.ts > o.at)", [$t00])) . "\n"; } catch (Throwable $e) { echo "ASK OFFER LOG ERR " . substr($e->getMessage(), 0, 100) . "\n"; }
